WITH filtered AS (SELECT id, store_id, product_id, quantity, last_restock, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock, DATE_TRUNC('week', last_restock) AS last_restock_period FROM inventory WHERE last_restock > DATE '2024-04-19' AND last_restock >= '2024-12-01') SELECT *, MAX(quantity) OVER (PARTITION BY product_id, store_id) AS product_id_max_quantity, AVG(quantity) OVER (PARTITION BY store_id, product_id ORDER BY days_since_last_restock, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS quantity_avg_3 FROM filtered;
